namespace sv_f6fe3a92a7ec42a8996765ffdbeeb56d.Client.Models;

public sealed record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public sealed record StatusUpdate(
    string Description,
    string Location,
    DateTimeOffset Timestamp);

using sv_f6fe3a92a7ec42a8996765ffdbeeb56d.Client.Models;

namespace sv_f6fe3a92a7ec42a8996765ffdbeeb56d.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

@page "/shipments/{TrackingNumber}"
@using sv_f6fe3a92a7ec42a8996765ffdbeeb56d.Client.Models
@using sv_f6fe3a92a7ec42a8996765ffdbeeb56d.Client.Services
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService
@inject ILogger<Shipment> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p><em>Loading shipment details for @TrackingNumber&hellip;</em></p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="alert alert-warning" role="alert">
        <p>No shipment found for tracking number <strong>@TrackingNumber</strong>.</p>
    </div>
}
else
{
    <h2>Shipment @_shipment.TrackingNumber</h2>
    <dl>
        <dt>Status</dt>
        <dd>@_shipment.Status</dd>
        <dt>Location</dt>
        <dd>@_shipment.Location</dd>
        <dt>Estimated Delivery</dt>
        <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
    </dl>

    <h3>Status History</h3>
    @if (_shipment.StatusUpdates.Count == 0)
    {
        <p>No status updates available.</p>
    }
    else
    {
        <table class="table">
            <thead>
                <tr>
                    <th>Time</th>
                    <th>Location</th>
                    <th>Description</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var update in _shipment.StatusUpdates)
                {
                    <tr>
                        <td>@update.Timestamp.ToString("g")</td>
                        <td>@update.Location</td>
                        <td>@update.Description</td>
                    </tr>
                }
            </tbody>
        </table>
    }
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = string.Empty;

    private ShipmentDetails? _shipment;
    private bool _loading;
    private string? _errorMessage;

    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request when the tracking number changes or on retry.
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _shipment = null;
        _errorMessage = null;
        _loading = true;
        StateHasChanged();

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Request was intentionally cancelled (navigation change or dispose). Do nothing.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
            StateHasChanged();
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

using sv_f6fe3a92a7ec42a8996765ffdbeeb56d.Client.Models;
using sv_f6fe3a92a7ec42a8996765ffdbeeb56d.Client.Services;

namespace sv_f6fe3a92a7ec42a8996765ffdbeeb56d.Services;

public sealed class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new ShipmentDetails(
            TrackingNumber: "TRK-001",
            Status: "In Transit",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 14, 17, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates:
            [
                new StatusUpdate("Package picked up", "New York, NY", new DateTimeOffset(2026, 7, 8, 9, 30, 0, TimeSpan.FromHours(-4))),
                new StatusUpdate("Departed facility", "New York, NY", new DateTimeOffset(2026, 7, 8, 14, 15, 0, TimeSpan.FromHours(-4))),
                new StatusUpdate("Arrived at sorting center", "Chicago, IL", new DateTimeOffset(2026, 7, 9, 6, 45, 0, TimeSpan.FromHours(-5))),
            ]),

        ["TRK-002"] = new ShipmentDetails(
            TrackingNumber: "TRK-002",
            Status: "Delivered",
            Location: "San Francisco, CA",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 9, 12, 0, 0, TimeSpan.FromHours(-7)),
            StatusUpdates:
            [
                new StatusUpdate("Package picked up", "Seattle, WA", new DateTimeOffset(2026, 7, 6, 10, 0, 0, TimeSpan.FromHours(-7))),
                new StatusUpdate("In transit", "Portland, OR", new DateTimeOffset(2026, 7, 7, 8, 20, 0, TimeSpan.FromHours(-7))),
                new StatusUpdate("Out for delivery", "San Francisco, CA", new DateTimeOffset(2026, 7, 9, 7, 0, 0, TimeSpan.FromHours(-7))),
                new StatusUpdate("Delivered", "San Francisco, CA", new DateTimeOffset(2026, 7, 9, 11, 32, 0, TimeSpan.FromHours(-7))),
            ]),

        ["TRK-003"] = new ShipmentDetails(
            TrackingNumber: "TRK-003",
            Status: "Label Created",
            Location: "Austin, TX",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 18, 18, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates:
            [
                new StatusUpdate("Shipping label created", "Austin, TX", new DateTimeOffset(2026, 7, 10, 8, 0, 0, TimeSpan.FromHours(-5))),
            ]),
    };

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

